import numpy as np
def lcs(x, y):
    m = len(x)
    n = len(y)
    # create a table to store the dp results
    table = np.zeros((m + 1, n + 1), dtype=int)
    # initialize the first row and column with 0
    for i in range(m + 1):
        table[i][0] = 0
    for j in range(n + 1):
        table[0][j] = 0
    # fill the table with LCS values
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if x[i - 1] == y[j - 1]:
                table[i][j] = table[i - 1][j - 1] + 1
            else:
                table[i][j] = max(table[i - 1][j], table[i][j - 1])
    # extract the longest common subsequence from the table
    lcs = []
    i, j = m, n
    while i > 0 and j > 0:
        if x[i - 1] == y[j - 1]:
            lcs.append(x[i - 1])
            i -= 1
            j -= 1
        elif table[i - 1][j] >= table[i][j - 1]:
            i -= 1
        else:
            j -= 1
    return "".join(reversed(lcs))
