#include <iostream>
using namespace std;
// recursive solution
int fib(int n) {
if (n <= 1) return n;
return fib(n - 1) + fib(n - 2);
}
// dynamic programming solution
int fibDP(int n) {
if (n <= 1) return n;
int a = 0, b = 1, c;
for (int i = 2; i <= n; ++i) {
c = a + b;
a = b;
b = c;
}
return b;
}
int main() {
int n;
cin >> n;
cout << fib(n) << endl;
cout << fibDP(n) << endl;
return 0;
}

